TAB_StoneOceanStory[1] = {1,"Ngươi không nên mạo hiểm sinh mạng để đến đây, nhưng ta rất tán thưởng ngươi ở dũng khí dám thách thức những điều chưa biết. ","Kujo Jotaro",235091,1}
