TAB_StoneOceanStory[3] = {1,"Kẻ địch ở đây thần bí mà còn xảo quyệt, cứ tiến một bước phải đảm bảo mỗi đồng đội đều sống lại, nếu không các ngươi đừng tiếp tục tiến lên. ","Kujo Jotaro",235091,1}
TAB_StoneOceanStory[4] = {1,"Nếu cần ta nguyện giúp ngươi một tay, cùng ngươi trừng trị những tên vì bản thân mà lợi dụng và chà đạp kẻ yếu kia!","Kujo Jotaro",235091,1}
